{
  "declined": "none",
  "criteria": [
    {
      "id": "task",
      "score": 3,
      "reason": "信的目的清楚，是邀請朋友來台灣並提出活動建議（如“Taipei 101 and Jiufen”, “go to the beach in Kenting”），但語氣與細節（時間、具體安排）較簡略，沒完全達到自然的口語書信註冊。"
    },
    {
      "id": "organization",
      "score": 3,
      "reason": "文章有開頭問候、邀請主旨和結尾收束，段落分配合理，但句子連接不夠流暢，某些資訊位置和過渡需改善（如“Jiufen is very old street it have many tea house”）。"
    },
    {
      "id": "vocabulary",
      "score": 3,
      "reason": "使用了合適的詞彙描述景點和活動（例如“delicious food”, “beach in Kenting”），但詞彙搭配與單複數、慣用語有錯誤（如“have many delicious food”, “tea house”應為“tea houses”或“teahouses”）。"
    },
    {
      "id": "grammar",
      "score": 2,
      "reason": "句子結構與文法錯誤較多，包括動詞形式、冠詞與介系詞錯誤（如“invite you come”, “in next summer”, “it have”），影響可讀性。"
    }
  ],
  "issues": [
    {
      "quote": "I want to invite you come to Taiwan in next summer.",
      "type": "grammar",
      "why": "缺少適當的動詞不定詞或介詞短語，且時間片語慣用說法不正確，應為 'invite you to come' 或 'invite you to visit', 以及 'next summer' 前不需介系詞 'in'.",
      "suggestion": "invite you to come to Taiwan next summer."
    },
    {
      "quote": "Taiwan is very beautiful and have many delicious food.",
      "type": "grammar",
      "why": "主詞與動詞數一致錯誤，且 'food' 為不可數，搭配 'many' 不恰當；慣用說法為 'delicious food' 或 'many delicious dishes'.",
      "suggestion": "Taiwan is very beautiful and has many delicious dishes."
    },
    {
      "quote": "Jiufen is very old street it have many tea house.",
      "type": "sentence",
      "why": "這是一個逗號或連接詞缺失的run-on sentence，且有數與單複數錯誤（'old street' 應為 'an old street' 或 'a historic town', 'it have' 應為 'it has', 'tea house' 應為複數）。",
      "suggestion": "Jiufen is a very old street, and it has many tea houses."
    }
  ],
  "more": [
    {
      "quote": "I can bring you go to Taipei 101 and Jiufen.",
      "type": "preposition",
      "why": "動詞搭配錯誤，應使用 'take you to' 或 'show you around', 'bring you go' 是逐字翻譯造成的不自然用法。",
      "suggestion": "I can take you to Taipei 101 and Jiufen."
    },
    {
      "quote": "We also can go to the beach in Kenting, but summer in Taiwan is very hot so you must to bring the sunscreen.",
      "type": "verb",
      "why": "'must to bring' 不是正確的助動詞用法，應為 'must bring' 或 'should bring'；另外可加入逗號或連接詞改善句子流暢。", 
      "suggestion": "We can also go to the beach in Kenting, but summer in Taiwan is very hot so you must bring sunscreen."
    },
    {
      "quote": "You can live in my home, my parents is very welcome you.",
      "type": "grammar",
      "why": "逗號拼接兩個完整子句造成run-on，且 'my parents is' 主詞動詞不一致，'welcome you' 用法略生硬，通常用 'would be happy to welcome you'.",
      "suggestion": "You can stay at my home; my parents would be very happy to welcome you."
    },
    {
      "quote": "Please tell me when you can come and I go to airport to pick you.",
      "type": "verb",
      "why": "時態與句子結構不完整，'and I go to airport to pick you' 應使用將來式或條件句，且缺少冠詞 'the airport'.",
      "suggestion": "Please tell me when you can come and I will go to the airport to pick you up."
    },
    {
      "quote": "Hope see you soon!",
      "type": "grammar",
      "why": "省略主詞與動詞不完整，正確常用寫法為 'Hope to see you soon' 或 'I hope to see you soon'.",
      "suggestion": "Hope to see you soon!"
    }
  ],
  "strengths": [
    {
      "quote": "If you come, I can bring you go to Taipei 101 and Jiufen.",
      "why": "清楚列出想帶朋友去的景點，顯示邀請的具體活動想法，這使邀請更具吸引力。"
    },
    {
      "quote": "We also can go to the beach in Kenting",
      "why": "提到不同類型的活動（城市景點與海灘），顯示多樣化的旅遊安排想法。"
    }
  ],
  "summary": "你的信很有誠意，內容也提出了具體的活動（如台北101、九份、墾丁）。接下來請注意動詞形式與句子連接（例如 'invite you to come', 'take you to'），修正單複數與冠詞使用，並把幾個冗長的句子分開或用連接詞串接，會讓信更自然流暢。"
}
